#!/usr/bin/env python3
"""Single deterministic generator. Browser studies, never native screenshots."""
from pathlib import Path
import json,html,re,calendar
R=Path(__file__).resolve().parents[1]
E=html.escape
pages=[]
groups={'headline':'01 · Headline figures','rows':'02 · Rows & columns','charts':'03 · Weight & chart labels','calendar':'04 · Calendar','forms':'05 · Goals & shared forms','capture':'06 · Meal, photo & menu sheets','technical':'Kept mono · Technical & named brand exception'}
def n(text,sites='',size=11,weight=400,keep=False,cls=''):
    if isinstance(sites,list):sites=' '.join(sites)
    return f'<span class="voice {"keep" if keep else "change"} {cls}" data-sites="{E(sites)}" data-size="{size}" data-weight="{weight}" style="font-size:{size}px;font-weight:{weight}">{E(str(text))}</span>'
def row(label,value):return f'<div class="readrow"><span>{label}</span>{value}</div>'
def section(title,content):return f'<section><h2>{title}</h2>{content}</section>'
def para(text):return f'<p>{text}</p>'
def field(label,value,sites,size=17,unit='',error=None):
    return f'<div class="field"><label>{label}</label><div class="write-line">{n(value,sites,size,500)}<span class="unit">{unit}</span></div>'+ (f'<p class="error">{n(error,"PaperFields-66")}</p>' if error else '')+'</div>'
def add(id,group,title,body,note='Only type changes. Values are fixed fictional specimens; no live account or write path.'):
    sites=sorted(set(s for a in re.findall(r'data-sites="([^"]*)"',body) for s in a.split()))
    body=body.replace('src="assets/a-__THEME__','data-src="assets/a-__THEME__')
    pages.append(dict(id=id,group=group,title=title,body=body,sites=sites,note=note))
ring='<svg class="ring" viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="40" fill="none" stroke="var(--inkline)" stroke-width="1"/><circle cx="50" cy="50" r="32" fill="none" stroke="var(--field)" stroke-width="10"/><path d="M50 18 A32 32 0 1 1 18 50" fill="none" stroke="var(--accent)" stroke-width="10"/><circle cx="50" cy="50" r="38" fill="none" stroke="var(--inkline)" stroke-width=".7" stroke-dasharray="1 4"/></svg>'
add('today-headline','headline','Today · Eaten / Goal', '<div class="hero">'+ring+'<div><p class="label">Eaten · Goal</p>'+n('1,684','Views-146',32,500)+'<span class="denominator"> / 2,126 kcal</span><p class="italic">442 kcal under</p></div></div>'+section('Same voice, different records',row('Zero recorded',n('0','Views-146',32,500))+row('Large value',n('11,888','Views-146',32,500))), 'Eaten changes; the existing serif denominator stays serif. Lower specimens test width, not additional Today metrics.')
add('history-headline','headline','History · Summary', '<div class="summary">'+''.join('<div>'+n(value,'HistoryLedgerViews-212',30,500)+f'<p class="italic">{label}</p></div>' for value,label in [('1,884','avg kcal'),('2','days over'),('6','logged')])+'</div>'+para(n('6-day logging streak','HistoryLedgerViews-190'))+section('No average available',n('—','HistoryLedgerViews-212',30,500)+'<p class="italic">avg kcal</p>'))
