add('food-rows','rows','Today · Food rows', food('Focaccia','420','1 portion','P 12g · C 58g · F 16g','focaccia')+food('Mortadella','186','1 portion','P 9g · C 1g · F 16g','mortadella'), 'Approved Variant A art: unchanged 56 px slot, 18 px/500 name, portion, right-aligned energy and macro line. No photos in rows.')
add('today-log','rows',"Today’s log", row('Today’s log',n('3 meals · 1,684 kcal','JournalUI-364'))+section('Lunch',para(n('12:10 PM','TodayLogViews-87'))+para(n('606 kcal','TodayLogViews-95',11,500))+food('Focaccia','420','1 portion','P 12g · C 58g · F 16g','focaccia'))+section('Multiple logs in one meal group',para(n('12:35 PM','TodayLogViews-115'))), 'SectionHeading detail and both time branches are included; reused food rows are also visible.')
