add('day-drill','rows','12 September',para(n('2,180 kcal','DayDrillDown-59',11,500)+' '+n('vs 2,126','DayDrillDown-63')+' '+n('· +54 over','DayDrillDown-67'))+food('Focaccia','420','1 portion','P 12g · C 58g · F 16g','focaccia')+section('Existing alternative branches',para(n('· on target','DayDrillDown-67'))+para(n('0 kcal','DayDrillDown-59',11,500))), 'Over, on-target and zero specimens. This reproduces source wording; it is not a correction to comparison logic.')
add('journal-folios','rows','Journal · Gutter date','<div class="gutterdemo"><div class="gutter">'+n('16.SEP.2026','JournalUI-48',9)+'</div><div><h2>Today</h2><p>Shared JournalPage</p><hr><h2>History</h2><p>Same margin voice</p><hr><h2>Goals</h2><p>Same margin voice</p></div></div>', 'The date keeps 0.5 px tracking and its rotated gutter position. Header dates already in other faces are not changed.')
add('peripheral-labels','rows','Auth & setup labels',section('Sign-in alternatives',para(n('or email','AuthView-52'))+para(n('Use a different email','AuthView-94')))+section('Setup navigation',para(n('Set up later','Onboarding-205')))+section('Conversation attribution',para(n('agent','Onboarding-256 Onboarding-271 Onboarding-282 Onboarding-377'))+para(n('you','Onboarding-369'))), 'These inherited mono labels are not technical strings: the candidate moves them to diary serif. “morsel” wordmarks are retained separately, per the explicit issue inventory.')
plot='<svg class="plot" viewBox="0 0 320 120" aria-label="Illustrative weight trace"><path d="M6 30 L55 24 L100 44 L150 43 L200 68 L250 63 L314 86 L314 116 L6 116Z" fill="var(--field)"/><path d="M6 30 L55 24 L100 44 L150 43 L200 68 L250 63 L314 86" fill="none" stroke="var(--positive)" stroke-width="1.6"/></svg>'
chart= row(n('Eaten − food target · kcal','WeightDeltaBand-22',10),n('±500','WeightDeltaBand-22',10))+'<div class="band"><i></i><i></i>'+n('?','WeightDeltaBand-58',12)+n('×','WeightDeltaBand-58',12)+n('·','WeightDeltaBand-58',12)+n('○','WeightDeltaBand-58',12)+'</div><div class="axis">'+''.join(n(d,'WeightDeltaBand-76',9) for d in ['10 Sep','12 Sep','14 Sep','16 Sep'])+'</div>'
add('weight-chart','charts','Weight trend',para(n('kg · 72 today · −1 over 30 days','JournalUI-364'))+plot+chart+para('<i>? food target unavailable · × no food log<br>· food log unavailable · ○ zero delta<br>+ above / − below food target</i>'), 'Chart text only: 9/10/12 px. Weight trace, missing-data symbols and axis positions are illustrative browser reconstructions; not Swift Charts proof.')
receipt=''
for label,value in [('Weight','72.4 kg'),('Food recorded','2,180 kcal'),('Dated baseline','2,126 kcal'),('Confirmed addition','+300 kcal'),('Food target','2,426 kcal'),('Eaten − target','−246 kcal')]:receipt+=row(label,n(value,'WeightDeltaBand-147'))
add('weight-receipt','charts','16 September',receipt+para('<i>Logged means at least one meal, not complete intake. These records do not explain weight changes.</i>'), 'All six receipt value rows; fixed fictional historical records. Confirmed addition is a specimen, never a suggestion.')
add('weight-missing','charts','Unavailable records', ''.join(row(label,n(value,'WeightDeltaBand-147')) for label,value in [('Weight','no weight recorded'),('Food recorded','food log unavailable'),('Dated baseline','unavailable'),('Confirmed addition','unavailable'),('Food target','unavailable'),('Eaten − target','food target unavailable')]), 'Nil branches retain honest text. No missing value is shown as zero; no Health interpretation.')
