cal+='<span></span><span></span>'
for day in range(1,31):cal+=f'<div class="day {"today" if day==16 else "future" if day>16 else ""}">'+n(day,'JournalCalendarView-104')+('<i></i>' if day in [1,4,8,10,11,13,14,16] else '<b></b>')+'</div>'
cal+='</div><p class="italic">Dots mark logged days. Future days remain unavailable.</p>'
add('calendar-month','calendar','Calendar',cal,'Month-grid digits and first-log range. Only typography changes; calendar selection/flip behaviour is not implemented or proposed here.')
goals=field('Calories','2126','GoalsEditor-240 PaperFields-91',22,'kcal')+'<div class="three">'+field('Protein','130','GoalsEditor-240 PaperFields-91',17,'g')+field('Carbs','266','GoalsEditor-240 PaperFields-91',17,'g')+field('Fat','71','GoalsEditor-240 PaperFields-91',17,'g')+'</div>'
add('goals-filled','forms','What are we aiming for?',para('Pick a direction, then change any number before I save it.')+'<div class="directions"><span>Cut</span><span>Maintain</span><span>Bulk</span></div>'+goals+para('<i>source: manual</i>'), 'Current Goals uses 22 px calories and 17 px macro fields. The 30 px Goals gauge named in the issue is absent at this pinned base; no fake gauge has been minted.')
