add('shared-field-states','forms','Ruled field states',field('Quantity','1','PaperFields-91',22,'portion')+field('Calories','0','PaperFields-91',17,'kcal')+field('Protein','Optional','PaperFields-91',17,'g'), 'Shared field typography only. “Optional” is a placeholder specimen, not zero. Only Goals supplies inline field errors at this base. Keyboard, focus and native Dynamic Type remain unverified.')
