for label,val in [('Usual computed target','2,126 kcal'),('Confirmed for this day','+300 kcal'),("Today’s food target",'2,426 kcal')]:training+=row(label,n(val,'TrainingFuelViews-87'))
add('training-receipt','rows','Existing training receipt',training+section('Missing baseline',row('Usual target',n('Unavailable','TrainingFuelViews-87'))), 'Baseline-only type comparison of the current receipt. Half (a) removes this from Today; this gallery does not reintroduce it or decide the half-(a) layout.')
add('training-amount','forms','Existing amount field',para('No amount suggested. Enter an addition from your own plan. This screen cannot assess adequate fuelling.')+field("Add to this day’s food target (kcal)",'Your amount','TrainingFuelViews-105',11,'')+para('<i>Blank first entry · placeholder only</i>'), 'Half-(a) overlap accounted for. The current 11 px medium font is compared without proposing its old layout for implementation. No numeric default.')
