add('meal-confidence','capture','Food · Provenance',section('Confidence',row('photo vision',n('92%','MealItemEditSheet-349',12)))+section('Needs review',row('photo vision',n('48%','MealItemEditSheet-349',12))+para(n('low confidence','MealItemEditSheet-356')))+section('Missing confidence',n('—','MealItemEditSheet-349',12)+para(n('confidence missing','MealItemEditSheet-356'))), 'Confidence lives in the detail sheet, never the row. The confidence formatter outputs whole percentages; both warning strings are verbatim from the pinned source.')
