add('add-photo','capture','Add meal · Photo',section('Photo ready',para(n('JPEG · 248 KB','AddMealPhotoSection-156'))+para(n('Remove','AddMealPhotoSection-165')))+section('Simulator availability',para(n('Camera is unavailable in this simulator.','AddMealPhotoSection-129'))), 'Photo bytes are not accessed. File-size specimen and nontechnical status/control copy change; photo contents are not invented.')
