add('technical-endpoints','technical','MCP endpoint',section('Onboarding',para(n(url,'Onboarding-329',11,keep=True)))+section('Settings',para(n(url,'SettingsView-136',11,keep=True)))+section('Not configured',para(n('MCP endpoint is not configured.','SettingsView-125',11,keep=True))), 'Unchanged mono: endpoint and its technical configuration status. URL is a display-only specimen; no link or request is made.')
