    add('technical-'+name,'technical',title+' · Setup prompt', '<pre>'+n(prompt,'Onboarding-303',11,keep=True)+'</pre>', 'Exact retained prompt text with the display endpoint substituted. Technical setup strings remain mono, including numbered steps. No commands execute.')
