# Structural font consumers do not emit numeric text themselves.
exclusions={'DesignSystem-296':'Unused morselTag helper: no production call site at base; no visible surface to mint.','SettingsView-159':'SF Symbol chevron (replay row), not text or numeric glyph. Retain native symbol sizing; not recreated as font proof.','SettingsView-208':'SF Symbol chevron (delete-account row), not text or numeric glyph. Retain native symbol sizing; not recreated as font proof.'}
sites=json.loads((R/'sources/source-sites.json').read_text());known={s['id'] for s in sites};seen={s for p in pages for s in p['sites']}
assert seen|set(exclusions)==known,(known-seen-set(exclusions),seen-known)
for s in sites:
    s['pages']=[p['id'] for p in pages if s['id'] in p['sites']]
    s['disposition']='rendered' if s['pages'] else 'not-visible'
    if s['id'] in exclusions:s['reason']=exclusions[s['id']]
(R/'coverage.json').write_text(json.dumps(dict(groups=groups,pages=[{k:v for k,v in p.items() if k!='body'} for p in pages],sites=sites,exclusions=exclusions),ensure_ascii=False,indent=2)+'\n')
head='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><link rel="stylesheet" href="style.css">'
for p in pages:
    content=head+f'<title>{E(p["title"])} · Morsel numeric study</title></head><body><div class="studybar"><span id="edition"></span><a href="index.html#{p["id"]}">Gallery</a></div><main id="specimen"><p class="kicker">Morsel · {E(groups[p["group"]])}</p><h1>{E(p["title"])}</h1>'+p['body']+'</main><footer><p>Source-derived HTML excerpt · not a native screenshot</p><p>'+E(p['note'])+'</p></footer><script src="specimen.js"></script></body></html>'
    (R/(p['id']+'.html')).write_text(content)
index=head+'<title>Morsel · Numeric voice before / after</title></head><body class="gallery"><main><p class="kicker">Morsel · #263 · Half (b)</p><h1>A diary voice for numbers.</h1><p class="lead">IBM Plex Mono → EB Garamond with tabular lining figures.<br>Same content, sizes, weights and colour roles. Both themes.</p><div class="notice"><strong>PROTOTYPE — awaiting owner approval.</strong><p>These are real browser renders of source-derived excerpts, not SwiftUI screenshots. Browser digit alignment is measured; native SwiftUI alignment remains UNVERIFIED under the no-Swift fence.</p></div><nav><a href="alignment-small.html?theme=paper">Digit alignment · small</a><a href="alignment-large.html?theme=paper">Digit alignment · large</a><a href="COVERAGE.md">Source coverage</a><a href="LIMITS.md">States & limits</a><a href="REPRODUCE.md">Reproduce</a></nav><div class="controls"><div class="theme-buttons" aria-label="Review theme"><button id="paper-button" data-theme-choice="paper" aria-pressed="true">Paper</button><button id="night-button" data-theme-choice="night" aria-pressed="false">Night</button></div><label>Group <select id="group"><option value="all">All groups</option>'+''.join(f'<option value="{k}">{v}</option>' for k,v in groups.items())+'</select></label></div><p>Paired excerpts preserve source typography and content; full native geometry, system symbols and navigation are not certified. Values are fictional specimens, not measured nutrition. Technical strings and the named brand exception are explicitly unchanged.</p>'
for group,title in groups.items():
    index+=f'<section class="group" data-group="{group}"><h2>{title}</h2><a href="evidence/contact-{group}-paper.png" data-contact="{group}">Contact sheet · Paper</a>'
    for p in [p for p in pages if p['group']==group]:
        index+=f'<article id="{p["id"]}"><h3>{E(p["title"])}</h3><p>{E(p["note"])}</p><div class="compare">'
        for version in ['before','after']:
            index+=f'<figure><a data-page="{p["id"]}" data-version="{version}" href="{p["id"]}.html?theme=paper&version={version}"><img loading="lazy" src="evidence/{p["id"]}-paper-{version}.png" data-shot="{p["id"]}-{version}" alt="{E(p["title"])} · Paper · {version}"></a><figcaption>{version.title()} · '+('IBM Plex Mono' if version=='before' or group=='technical' else 'EB Garamond · tabular')+'</figcaption></figure>'
        index+='</div><details><summary>Source call sites</summary><p>'+E(', '.join(p['sites']))+'</p></details></article>'
    index+='</section>'
index+='</main><script src="gallery.js"></script></body></html>'
(R/'index.html').write_text(index)
for group,sizes in [('small',[9,10,11,12,14]),('large',[17,22,30,32])]:
    proof=head+'<title>Rendered digit alignment · '+group+'</title></head><body class="proof"><main><p class="kicker">Actual browser layout · not SwiftUI</p><h1>Equal advances, not equal boxes.</h1><p>Unconstrained inline text. Same bundled Garamond file. First line: tabular; second: proportional negative control. No grid cells or fixed glyph widths.</p>'
    for size in sizes:
        proof+=f'<section><h2>{size} px</h2>'
        for feature in ['tnum','pnum']:
            proof+=f'<div class="digitline" data-size="{size}" data-feature="{feature}" style="font-size:{size}px;font-feature-settings:\'{feature}\' 1,\'lnum\' 1">'+''.join(f'<span class="digit">{i}</span>' for i in range(10))+'</div>'
        proof+=f'<div class="columns" data-size="{size}" style="font-size:{size}px">'+''.join('<div>'+s+'</div>' for s in ['11111','22222','88888'])+'</div></section>'
    proof+='<p>Raw DOM Range advances and actual platform-font names are retained in evidence/alignment.json. Native verdict: UNVERIFIED.</p><a href="index.html">Gallery</a></main><script>document.documentElement.dataset.theme=new URLSearchParams(location.search).get("theme")||"paper";window.ready=true;</script></body></html>'
    (R/('alignment-'+group+'.html')).write_text(proof)
print(json.dumps(dict(pages=len(pages),rendered_sites=len(seen),excluded_sites=len(exclusions),themes=2,versions=2)))
